function treeHash(root,scopes){const h=createHash('sha256');let files=0;function visit(rel){const p=path.join(root,rel);if(!fs.existsSync(p))return;for(const d of fs.readdirSync(p,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))){if(['node_modules','__pycache__','_runtime'].includes(d.name))continue;const r=path.join(rel,d.name);if(d.isDirectory())visit(r);else if(d.isFile()){h.update(r).update('\0').update(fs.readFileSync(path.join(root,r))).update('\0');files++;}}}scopes.forEach(visit);return {scopes,files,sha256:h.digest('hex')};}
