async function actualGeometry(page){return page.evaluate(async()=>{const {p,runtime}=window.__ownershipRuntime(),rows=runtime.cadScene.source.parts;const meshes=new Map();for(const row of rows)if(!meshes.has(row.componentId))meshes.set(row.componentId,row.sourceMesh);const output=[];for(const[cid,m]of meshes){const arrays=[];for(const key of ['vertices','indices','normals','colors','edge_indices','cadEdgePositions','cadEdgeIndices','guide_line_segments'])if(ArrayBuffer.isView(m[key])){const v=m[key],digest=await crypto.subtle.digest('SHA-256',new Uint8Array(v.buffer,v.byteOffset,v.byteLength));arrays.push({key,type:v.constructor.name,length:v.length,bytes:v.byteLength,sha256:[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')});}output.push({cid,level:Number(m.lodLevel)||0,key:m.lodKey||null,arrays});}return {components:output,occurrences:rows.map(r=>({id:r.id,cid:r.componentId,transform:r.transform})),selected:p.selectedReferenceIds.slice()}})}
async function run(condition,stage,index,servers){const kind=condition==='old'?'old':'candidate',batchSize=condition==='old'?null:Number(condition.slice(-1)),srv=servers[kind],name=`viewer-batch-v3-${stage}-${condition}-${index}-20260910`,out=path.join(results,name+'.json');if(fs.existsSync(out))throw new Error('Refusing overwrite '+out);const r={condition,stage,index,startedAt:new Date().toISOString(),qualification:'Planetary nine-part private browser. Same current Python backend and canonical store; independent frozen frontend conditions. No forced GC or allocation sampling. First refined draw is a WebGL submission after actual CPU/Three adoption, not GPU completion. Composition call count is inferred from publication notifications; composition duration is not separately instrumented.',before:sourceProof(kind),served:await servedProof(srv),server:srv.proof,fixture:{path:path.join(fixture,'planetary.step'),sha256:hash(fs.readFileSync(path.join(fixture,'planetary.step')))},samples:[],errors:[],httpFailures:[],peakRss:{},assertions:{}};
 const profile=fs.mkdtempSync(path.join(os.tmpdir(),'batch-medium-'));let context,timer,sampler;try{context=await chromium.launchPersistentContext(profile,{headless:true,viewport:{width:1400,height:900},args:['--use-angle=metal','--enable-precise-memory-info']});r.browserVersion=context.browser()?.version();timer=setTimeout(()=>{r.guard='45-second limit';context.close().catch(()=>{})},45000);sampler=setInterval(()=>{try{const s=processMemoryFromPs(execFileSync('/bin/ps',['-axww','-o','pid=,ppid=,rss=,args='],{encoding:'utf8'}),profile);mergeProcessPeak(r.peakRss,s);if(s.renderer?.largestPidBytes>2147483648){r.guard='2 GiB largest renderer';context.close().catch(()=>{})}}catch{}},500);const page=context.pages()[0];await page.addInitScript(installInspection);await page.addInitScript(installWorkerProbe);await page.addInitScript(installCacheWriteProbe);await page.addInitScript(installViewerResourceTiming);await page.addInitScript(installProbe,batchSize);page.setDefaultTimeout(4000);page.on('pageerror',e=>r.errors.push(String(e)));page.on('response',response=>{if(response.status()>=400)r.httpFailures.push({url:response.url(),status:response.status()})});
 const sample=async label=>{const s={label,...await page.evaluate(()=>window.__batchSample())};r.samples.push(s);return s};
 const stable=async label=>{let goodSince=null;for(let i=0;i<120;i++){const s=await sample(label),good=s.sceneRecords===9&&s.meshCost?.final&&s.meshCost?.componentCount===9&&s.source===s.actualSource&&s.adoption?.pending===0&&!s.lod?.busy&&!s.lod?.pendingEvaluation&&s.lod?.qualitySettled&&s.lod?.unmetTargets?.length===0&&s.memory?.reservationCount===0&&s.workers.live===0&&s.cacheWrites.active===0&&s.draw.last>=(s.sceneSync.last?.atMs||0)-1;if(good){goodSince??=s.at;if(s.at-goodSince>=300){const last=await page.evaluate(()=>{const p=window.__batchProbe,c=p.current;if(c){c.settledAt=performance.now();c.sceneUpdates=(window.__cadSceneSync?.count||0)-c.sceneCountBase;c.sceneMs=(window.__cadSceneSync?.totalMs||0)-c.sceneMsBase;c.publications=p.publications.length-c.publicationBase;}return c?{...c}:null});if(last)r.phaseResults.push(last);return s}}else goodSince=null;await pause(75)}throw new Error('Policy did not settle: '+label)};
 r.phaseResults=[];r.navigationAt=new Date().toISOString();await page.goto(srv.origin+'/?file=planetary.step',{waitUntil:'domcontentloaded',timeout:15000});r.initial=await stable('initial');
 const part=page.getByLabel('Component carrier_plate',{exact:true});await part.getByText('carrier_plate',{exact:true}).click();await page.getByRole('button',{name:'Expand carrier_plate',exact:true}).click();await page.waitForFunction(()=>window.__ownershipInspect().selectors?.references.length>0);const faces=await page.getByRole('treeitem').evaluateAll(rows=>rows.map(x=>x.getAttribute('aria-label')).filter(x=>/^Face /i.test(x||'')));if(!faces.length)throw new Error('No visible Face row');await page.getByLabel(faces[0],{exact:true}).click();r.selected=await stable('selected');
 for(const[label,value]of [['near',800],['returned',100]]){await page.evaluate(l=>window.__batchMark(l),label);const z=page.getByLabel('Zoom level percent',{exact:true});await z.fill(String(value));await z.press('Enter');r[label]=await stable(label);r[label+'Geometry']=await actualGeometry(page);}
