efore)===JSON.stringify(r.after);r.assertions.completeAllPhases=[r.initial,r.selected,r.near,r.returned].every(s=>s.sceneRecords===9&&s.source===s.actualSource&&s.meshCost.componentCount===9);r.assertions.qualitySatisfied=[r.initial,r.selected,r.near,r.returned].every(s=>s.lod.qualitySettled&&s.lod.unmetTargets.length===0);r.assertions.selectionPersists=r.selected.selection.selectedReferenceIds.length>0&&[r.near,r.returned].every(s=>JSON.stringify(s.selection.selectedReferenceIds)===JSON.stringify(r.selected.selection.selectedReferenceIds));r.assertions.selectorsMatch=[r.selected,r.near,r.returned].every(s=>s.selectors.faceCoverage.length>0&&s.selectors.faceCoverage.every(f=>s.partRows.find(p=>p.id===f.id)?.triangles===f.triangles));r.assertions.ownersDrain=r.final.memory.reservationCount===0&&r.final.adoption.pending===0&&r.final.workers.live===0&&(!r.final.lod.staging||r.final.lod.staging.owners===0);r.assertions.batchBound=condition==='old'||(r.final.lod.batching.maxOccupied<=batchSize&&r.final.lod.batching.loaderLanes===1&&r.final.batch.max.loading<=1);r.assertions.noGuard=!r.guard;r.assertions.zeroErrors=r.errors.length===0;r.assertions.refinedDraw=r.phaseResults.some(p=>p.firstRefinedDrawAt>=p.firstAdoptionAt);
 if(stage!=='warmup')r.assertions.warmCache=r.httpFailures.filter(x=>x.url.includes('/__tess_cache/')).length===0&&r.workerRequests.filter(x=>x.capabilities?.render).every(x=>x.cachedBytes>0);
 r.outcome=Object.values(r.assertions).every(Boolean)?'passed':'failed';if(stage==='smoke'){r.screenshot=path.join(fixture,name+'.png');await page.screenshot({path:r.screenshot});}
 }catch(e){r.outcome='failed';r.error=String(e.stack||e)}finally{clearTimeout(timer);clearInterval(sampler);await context?.close().catch(()=>{});r.finishedAt=new Date().toISOString();fs.writeFileSync(out,JSON.stringify(r,null,2)+'\n');console.log(JSON.stringify({condition,stage,index,outcome:r.outcome,error:r.error,assertions:r.assertions,phases:r.phaseResults,peakRendererMiB:(r.peakRss.renderer?.largestPidBytes||0)/1048576,out}));}return r;
}
const servers={};try{servers.old=await server('old');servers.candidate=await server('candidate');console.log(JSON.stringify({servers:Object.fromEntries(Object.entries(servers).map(([k,v])=>[k,{origin:v.origin,pid:v.child.pid,dist:v.dist}]))}));const mode=process.argv[2]||'smoke';const sequence=mode==='measure'?['candidate1','candidate4','old','candidate4','old','candidate1','old','candidate1','candidate4']:['old','candidate4','old','candidate1','candidate4'];let i=0;for(const condition of sequence){const stage=mode==='measure'?'measure':i<2?'warmup':'smoke';const r=await run(condition,stage,++i,servers);if(r.outcome!=='passed'){process.exitCode=1;break}}}finally{for(const s of Object.values(servers)){s.child.kill('SIGTERM');await Promise.race([new Promise(resolve=>s.child.once('exit',resolve)),pause(3000)]);}console.log(JSON.stringify({closedOwnedServers:true,finishedAt:new Date().toISOString()}));}

