export const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
export function installInspection(){
 const ids=new WeakMap();let counter=0;
 const id=o=>{if(!o||typeof o!=='object')return null;if(!ids.has(o))ids.set(o,++counter);return ids.get(o)};
 const find=()=>{
  let el=document.querySelector('canvas'),f;
  while(el&&!f){const key=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));if(key)f=el[key];el=el.parentElement}
  for(let i=0;f&&i<150;i++,f=f.return){const p=f.memoizedProps;if(p&&Array.isArray(p.selectedPartIds)&&Array.isArray(p.selectedReferenceIds)&&Object.hasOwn(p,'selectorRuntime')){
   let runtime=null;for(let h=f.memoizedState,n=0;h&&n<500;h=h.next,n++){const v=h.memoizedState?.current;if(v?.renderer&&v?.modelGroup){runtime=v;break}}
   return {p,runtime};
  }}return{};
 };
 window.__ownershipInspect=()=>{
  const {p,runtime}=find(),selector=p?.selectorRuntime,rows=runtime?.displayRecords||[];
  const refs=selector?.references||[];
  const columns=selector?.proxy?.faceRunColumns||[],runs=selector?.proxy?.faceRuns;
  const sums=new Map();for(let n=0; n<(runs?.length||0); n+=columns.length){const row=runs[n+columns.indexOf('occurrenceRow')], count=runs[n+columns.indexOf('triangleCount')];sums.set(row,(sums.get(row)||0)+count)}
  const partRows=(p?.meshData?.parts||[]).map(x=>({id:x.id,cid:x.componentId,level:x.sourceMesh?.lodLevel,mesh:id(x.sourceMesh),triangles:Math.floor((x.sourceMesh?.indices?.length||0)/3)}));
  return {at:performance.now(),selection:p?{selectedPartIds:p.selectedPartIds.slice(),selectedReferenceIds:p.selectedReferenceIds.slice(),hiddenPartIds:p.hiddenPartIds.slice()}:null,
   source:id(p?.meshData),actualSource:id(runtime?.cadScene?.source),sceneRecords:rows.length,
   partRows,recordRows:rows.map(r=>({id:r.partId,mesh:id(r.sourcePart?.sourceMesh),visible:r.mesh?.visible,selected:r.selected,materialVisible:r.material?.visible})),
   selectors:selector?{id:id(selector),stepHash:selector.stepHash,occurrences:selector.occurrences?.map(r=>r.id),occurrenceIds:[...(selector.occurrenceIdByRowIndex||[])],faceRunColumns:columns,faceRunCount:runs?runs.length/columns.length:0,faceCoverage:[...sums].map(([row,triangles])=>({id:selector.occurrenceIdByRowIndex.get(row),triangles})),references:refs.slice(0,6).map(x=>({id:x.id,partId:x.partId,type:x.selectorType,selector:x.normalizedSelector}))}:null,
   adoption:window.__cadLodSceneAdoption?.(),lod:window.__cadViewportLod?.(),memory:window.__cadViewerMemoryPolicySnapshot?.(),probe:window.__cadRenderMemoryProbe?.(),workers:{...window.__cadWorkerProbe},meshCost:window.__cadMeshCost,
