  report.afterProof=await proof();report.assertions.sourceAndClientStable=true;report.assertions.noGuard=!report.guard;
  report.outcome=Object.values(report.assertions).every(x=>x===true)?'passed':'failed';
 }catch(e){report.outcome='failed';report.error=String(e.stack||e)}finally{
  clearTimeout(watchdog);clearInterval(sampler);await context?.close().catch(()=>{});report.finishedAt=new Date().toISOString();
  fs.writeFileSync(out,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({outcome:report.outcome,error:report.error,assertions:report.assertions,out}));
