export {repo,origin};

import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');

function fingerprint(roots, ignored = new Set()) {
  const hash = createHash('sha256');
  function visit(directory) {
    if (!fs.existsSync(directory)) return;
    for (const entry of fs.readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      if (ignored.has(entry.name)) continue;
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) visit(file);
      else if (entry.isFile()) hash.update(path.relative(repo, file)).update('\0').update(fs.readFileSync(file)).update('\0');
    }
  }
  roots.forEach(root => visit(path.join(repo, root)));
  return hash.digest('hex');
}

export function viewerRuntimeFingerprint() {
  return {
    source: fingerprint(['apps/viewer/src', 'packages/cadgen-js/src', 'packages/cadgen/src/cadgen'], new Set(['_runtime', '__pycache__'])),
    builtClient: fingerprint(['apps/viewer/dist']),
    installedDependencies: Object.fromEntries(['apps/viewer', 'packages/cadgen-js'].map(root => [root,
      Object.fromEntries(['three', 'three-mesh-bvh', 'react'].map(name => {
        const file = path.join(repo, root, 'node_modules', name, 'package.json');
        if (!fs.existsSync(file)) return [name, null];
        const bytes = fs.readFileSync(file);
        return [name, {
          version: JSON.parse(bytes).version,
          packageJson: fs.realpathSync(file),
          packageJsonSha256: createHash('sha256').update(bytes).digest('hex'),
        }];
      }))
    ])),
  };
}

// A disk fingerprint alone cannot prove which checkout a long-lived server
// serves. Validate its entry document and referenced assets before measuring.
export async function verifyServedViewerClient(origin, {
  dist = path.join(repo, 'apps/viewer/dist'), fetchImpl = fetch,
} = {}) {
  const localIndex = fs.readFileSync(path.join(dist, 'index.html'));
  const assets = [...localIndex.toString().matchAll(/(?:src|href)="(\/assets\/[^"?#]+)"/g)].map(match => match[1]);
  const paths = ['/', ...new Set(assets)];
  const files = [];
  for (const pathname of paths) {
    const response = await fetchImpl(new URL(pathname, origin), { signal: AbortSignal.timeout(5000), cache: 'no-store' });
    if (!response.ok) throw new Error(`Served client proof failed: ${pathname} returned ${response.status}`);
    const bytes = Buffer.from(await response.arrayBuffer());
    const local = pathname === '/' ? localIndex : fs.readFileSync(path.join(dist, pathname));
    const sha256 = createHash('sha256').update(bytes).digest('hex');
    if (!bytes.equals(local)) throw new Error(`Served client differs from ${dist}: ${pathname}`);
    files.push({ path: pathname, bytes: bytes.length, sha256 });
  }
  return { dist, matches: true, files };
}

// Browser init script: worker-isolate ownership independent of the app ledger.
export function installWorkerProbe() {
  const OriginalWorker = window.Worker;
  if (typeof OriginalWorker !== 'function') return;
  const stats = { created: 0, terminated: 0, live: 0, peakLive: 0 };
  window.__cadWorkerProbe = stats;
  const terminated = new WeakSet();
  const liveWorkers = new Set();
  let stopped = false;
  const requests = [];
  window.__cadWorkerRequests = requests;
  // Only the disposable diagnostic page calls this after recording failure.
  // Also terminate later workers immediately: queued cache/publication work
  // can otherwise start another isolate during failure diagnostics. Main-thread
  // callbacks can still drain; this is not proof that the whole page is idle.
  // It cannot make the failed run pass or affect the user's viewer.
  window.__cadStopMemoryProbeWorkers = () => {
    stopped = true;
    const count = liveWorkers.size;
    for (const worker of [...liveWorkers]) worker.terminate();
    return count;
  };
  window.Worker = class extends OriginalWorker {
    constructor(...args) {
      super(...args);
      liveWorkers.add(this);
      stats.created += 1;
      this.__probeId = stats.created;
      stats.live += 1;
      stats.peakLive = Math.max(stats.peakLive, stats.live);
      if (stopped) this.terminate();
      this.addEventListener?.('message', event => {
        const request = requests.find(item => item.worker === this.__probeId && item.id === event.data?.id);
        if (request) { request.finishedAt = performance.now(); request.ok = event.data?.ok; }
      });
    }
    postMessage(message, ...rest) {
      if (message?.type === 'loadSurf') {
        if (requests.length >= 128) requests.shift();
        requests.push({ worker: this.__probeId, id: message.id, url: String(message.url),
          startedAt: performance.now(), capabilities: { ...message.capabilities },
          tessellation: { ...message.tessellation }, cachedBytes: message.cachedEntry?.byteLength || 0 });
      }
      return super.postMessage(message, ...rest);
    }
    terminate() {
      if (!terminated.has(this)) {
        liveWorkers.delete(this);
        terminated.add(this);
        stats.terminated += 1;
        stats.live -= 1;
      }
      return super.terminate();
    }
  };
}

// Harness-only native Resource Timing. No fetch wrapper, response clones or
// per-request observer allocations; the browser owns a bounded entry buffer.
export function installViewerResourceTiming() {
  const state = { bufferSize: 8192, maxReportedEntries: 4096, bufferFullEvents: 0, installed: false };
  window.__cadResourceTimingProbe = state;
  try {
    performance.setResourceTimingBufferSize(state.bufferSize);
    performance.addEventListener('resourcetimingbufferfull', () => { state.bufferFullEvents++; });
    state.installed = true;
  } catch (error) { state.error = String(error.message || error); }
}

// Called after the acceptance grade. Timing fields share the window's time
// origin with the worker postMessage and LOD/adoption probes. A worker's own
// fetch timeline is separate and is deliberately not intercepted here.
export function collectViewerResourceTiming({ cutoffEpochMs } = {}) {
  const state = window.__cadResourceTimingProbe || {};
  const origin = window.location.origin;
  const cutoffAt = Number.isFinite(cutoffEpochMs) ? cutoffEpochMs - performance.timeOrigin : performance.now();
  const fields = ['startTime', 'duration', 'workerStart', 'fetchStart', 'domainLookupStart',
    'domainLookupEnd', 'connectStart', 'secureConnectionStart', 'connectEnd', 'requestStart',
    'responseStart', 'responseEnd', 'transferSize', 'encodedBodySize', 'decodedBodySize', 'responseStatus'];
  const all = performance.getEntriesByType('resource');
  const entries = [];
  let matchingEntries = 0, afterCutoffEntries = 0;
  for (const item of all) {
    let url;
    try { url = new URL(item.name, origin); } catch { continue; }
    if (url.origin !== origin) continue;
    let route, key;
    if (url.pathname === '/__tess_cache/batch') {
      route = 'tess-batch'; key = '';
    } else if (url.pathname.startsWith('/__tess_cache/') && url.pathname.endsWith('.tess')) {
      route = 'tess-entry'; key = url.pathname.slice('/__tess_cache/'.length);
    } else {
      const file = url.pathname === '/__cad/store' ? url.searchParams.get('file') : url.pathname;
      if (!file?.endsWith('.surf')) continue;
      route = 'surf'; key = file.split('/').at(-1);
    }
    if (Number.isFinite(item.responseEnd) && item.responseEnd > cutoffAt) { afterCutoffEntries++; continue; }
    matchingEntries++;
    if (entries.length >= (state.maxReportedEntries || 4096)) continue;
    // Route/key are bounded identifiers, not full model paths or response data.
    const entry = { route, key: key.slice(0, 512), initiatorType: String(item.initiatorType || '').slice(0, 40),
      nextHopProtocol: String(item.nextHopProtocol || '').slice(0, 40) };
    for (const field of fields) entry[field] = Number.isFinite(item[field]) ? item[field] : null;
    entries.push(entry);
  }
  return { ...state, collectedAfterGrade: true, collectedAt: performance.now(), timeOrigin: performance.timeOrigin,
    cutoffAt, totalBufferedEntries: all.length, matchingEntries, afterCutoffEntries,
    truncated: (state.bufferFullEvents || 0) > 0 || matchingEntries > entries.length,
    coverage: 'Window same-origin tess-cache and SURF requests only. Worker-owned SURF fetches have separate timelines and are absent. No HTTP method, server CPU, JS arrayBuffer materialization, dispatch/adoption or GPU completion timing is inferred. Zero/unsupported timing fields are preserved. Entries ending after the grade are excluded; incomplete requests may be absent.',
    entries };
}

// Optional profiling and failure-side collection for this harness's own page.
// Numeric summaries only: probes never keep transferred mesh/cache payloads.
export function installCacheWriteProbe() {
  const original = window.fetch;
  const stats = { active: 0, activeBytes: 0, peakActive: 0, peakBytes: 0, total: 0, totalBytes: 0 };
  window.__cadCacheWriteProbe = stats;
  window.fetch = async function(input, init) {
    const url = String(input?.url || input);
    const tracked = String(init?.method || input?.method || 'GET').toUpperCase() === 'POST'
      && url.includes('/__tess_cache/') && !url.endsWith('/batch');
    if (!tracked) return original.apply(this, arguments);
    const size = Number(init?.body?.byteLength ?? init?.body?.size) || 0;
    stats.active += 1;
    stats.activeBytes += size;
    stats.total += 1;
    stats.totalBytes += size;
    stats.peakActive = Math.max(stats.peakActive, stats.active);
    stats.peakBytes = Math.max(stats.peakBytes, stats.activeBytes);
    try { return await original.apply(this, arguments); }
    finally { stats.active -= 1; stats.activeBytes -= size; }
  };
}

export function summarizeSamplingProfile(profile, limit = 30) {
  const rows = [];
  const visit = (node, parents) => {
    const frame = node.callFrame || {};
    const name = `${frame.functionName || '(anonymous)'} ${frame.url || ''}:${(frame.lineNumber ?? -1) + 1}`;
    if (node.selfSize > 0) rows.push({ bytes: node.selfSize, site: name, callers: parents.slice(-5) });
    for (const child of node.children || []) visit(child, [...parents, name]);
  };
  if (profile?.head) visit(profile.head, []);
  rows.sort((a, b) => b.bytes - a.bytes);
  return { sampledBytes: rows.reduce((sum, row) => sum + row.bytes, 0), sites: rows.length, largestSites: rows.slice(0, limit) };
}

async function requestSourceHints(requests, origin) {
  const recent = [...new Map((requests || []).slice(-8).map(row => [row.url, row])).values()];
  return Promise.all(recent.map(async row => {
    const hint = { worker: row.worker, requestId: row.id, url: row.url, tessellation: row.tessellation };
    try {
      const response = await fetch(new URL(row.url, origin), { method: 'HEAD', signal: AbortSignal.timeout(1500) });
      const bytes = Number(response.headers.get('content-length'));
      return { ...hint, status: response.status, sourceBytes: response.ok && bytes > 0 ? bytes : null };
    } catch (error) { return { ...hint, error: String(error.message || error) }; }
  }));
}

async function workerHeap(cdp, target, bounded) {
  let sessionId;
  let listener;
  try {
    ({ sessionId } = await bounded(cdp.send('Target.attachToTarget', { targetId: target.targetId, flatten: false }), 1500));
    const reply = new Promise((resolve, reject) => {
      listener = event => {
        if (event.sessionId !== sessionId) return;
        const message = JSON.parse(event.message);
        if (message.id !== 1) return;
        if (message.error) reject(new Error(message.error.message));
        else resolve(message.result);
      };
      cdp.on('Target.receivedMessageFromTarget', listener);
    });
    const [, heap] = await Promise.all([
      bounded(cdp.send('Target.sendMessageToTarget', {
        sessionId, message: JSON.stringify({ id: 1, method: 'Runtime.getHeapUsage' }),
      }), 1500),
      bounded(reply, 1500),
    ]);
    return { targetId: target.targetId, url: target.url, ...heap };
  } catch (error) {
    return { targetId: target.targetId, url: target.url, error: String(error.message || error) };
  } finally {
    if (listener) cdp.off('Target.receivedMessageFromTarget', listener);
    if (sessionId) await bounded(cdp.send('Target.detachFromTarget', { sessionId }), 500).catch(() => {});
  }
}

export async function collectHeapDiagnostics({ page, cdp, bounded, sampleRss, failed, sampling }) {
  const result = { failureSide: failed, workersStopped: false, mainThreadQuiescenceVerified: false, errors: [] };
  const attempt = async (label, operation) => {
    try { return await operation(); }
    catch (error) { result.errors.push({ phase: label, error: String(error.message || error) }); return null; }
  };
  result.before = { rss: sampleRss(), page: await attempt('before-page', () => bounded(cdp.send('Runtime.getHeapUsage'), 2000)) };
  result.before.dom = await attempt('before-dom', () => bounded(cdp.send('Memory.getDOMCounters'), 1500));
  const { targetInfos } = await bounded(cdp.send('Target.getTargets'), 1500).catch(() => ({ targetInfos: [] }));
  result.before.workers = await Promise.all(targetInfos.filter(target => target.type === 'worker').slice(0, 8)
    .map(target => workerHeap(cdp, target, bounded)));
  if (sampling) {
    const profile = await attempt('before-sampling', () => bounded(cdp.send('HeapProfiler.getSamplingProfile'), 2000));
    if (profile) result.before.sampling = summarizeSamplingProfile(profile.profile);
  }
  if (failed) {
    result.stoppedWorkers = await attempt('stop-workers', () => bounded(page.evaluate(() => window.__cadStopMemoryProbeWorkers?.() || 0), 1000));
    result.workersStopped = result.stoppedWorkers !== null;
  }
  await attempt('collect-garbage', () => bounded(cdp.send('HeapProfiler.collectGarbage'), 2500));
  await new Promise(resolve => setTimeout(resolve, 1000));
  // Already-queued publications can allocate during the settling interval.
  // Collect again before sampling; the former GC-then-wait sample mixed retained
  // objects with that new garbage. Even this bounded drain is not an idle proof.
  await attempt('collect-garbage-after-settle', () => bounded(cdp.send('HeapProfiler.collectGarbage'), 2500));
  result.after = {
    rss: sampleRss(),
    page: await attempt('after-page', () => bounded(cdp.send('Runtime.getHeapUsage'), 2000)),
    dom: await attempt('after-dom', () => bounded(cdp.send('Memory.getDOMCounters'), 1500)),
    state: await attempt('after-state', () => bounded(page.evaluate(() => ({
      heapUsed: performance.memory?.usedJSHeapSize || 0,
      workers: window.__cadWorkerProbe ? { ...window.__cadWorkerProbe } : null,
      workerRequests: window.__cadWorkerRequests || [],
      cacheWrites: window.__cadCacheWriteProbe ? { ...window.__cadCacheWriteProbe } : null,
      owned: window.__cadRenderMemoryProbe?.() || null,
    })), 1500)) || {},
  };
  if (sampling) {
    const profile = await attempt('after-sampling', () => bounded(cdp.send('HeapProfiler.stopSampling'), 2000));
    if (profile) result.after.sampling = summarizeSamplingProfile(profile.profile);
  }
  result.sourceHints = await requestSourceHints(result.after.state.workerRequests, page.url());
  return result;
}

import { isCompletePublication } from './completion.mjs';

export function preservesCompleteAdaptiveView(probe, { occurrences }, modelKey) {
  return !!modelKey && probe.modelKey === modelKey
    && probe.renderMemoryProbe?.occurrences === occurrences
    && probe.sceneSync?.records === occurrences;
}

// A completed draw is distinct from policy convergence. Denied refinement can
// leave a stable, complete view; report that outcome without calling it full detail.
export function adaptiveStatus(probe, { components, occurrences }) {
  const complete = isCompletePublication(probe)
    && probe.meshCost.totalComponents === components
    && probe.meshCost.occurrenceCount === occurrences;
  const drawn = complete && probe.draw?.lastAt >= probe.meshCost.at;
  const lod = probe.viewportLod;
  const counts = Object.values(lod?.levelCounts || {}).reduce((sum, value) => sum + value, 0);
  const schedulerIdle = lod?.componentCount === components && counts === components
    && lod.minimumLevel === 0 && !lod.busy && !lod.pendingEvaluation;
  const resourcesIdle = probe.memoryPolicy?.reservationCount === 0
    && probe.cacheWrites?.active === 0 && probe.workers?.live === 0;
  const unmetTargets = Array.isArray(lod?.unmetTargets) ? lod.unmetTargets : [];
  const qualitySettled = lod?.qualitySettled === true && unmetTargets.length === 0;
  const limited = !!probe.memoryPolicy?.lastLimitation
    || unmetTargets.some(({ reason }) => reason === 'memory-denied' || reason === 'memory-pressure');
  const failed = Number(lod?.failedLevels) || 0;
  const detailOutcome = limited ? 'budget-limited' : failed ? 'failed-levels'
    : qualitySettled ? 'policy-satisfied' : 'unmet-targets';
  return {
    complete, drawn, schedulerIdle, resourcesIdle, qualitySettled, unmetTargets,
    stableCandidate: drawn && schedulerIdle && resourcesIdle && detailOutcome !== 'unmet-targets',
    detailOutcome,
    limitation: probe.memoryPolicy?.lastLimitation || null,
    failedLevels: failed,
  };
}

export function createAdaptiveStabilityWindow(stableMs = 2000) {
  let key = null, since = null;
  return (probe, expected, now) => {
    const status = adaptiveStatus(probe, expected);
    // Camera changes and any new publication reset the interval even when the
    // scheduler happens to look idle between two operations.
    const nextKey = JSON.stringify([
      probe.modelKey, probe.meshCost?.at, probe.events?.lodCount,
      probe.events?.cameraCount, probe.cameraZoomPercent, probe.viewportLod?.levelCounts,
      status.detailOutcome, status.failedLevels, status.qualitySettled, status.unmetTargets,
    ]);
    if (!status.stableCandidate) { key = null; since = null; }
    else if (key !== nextKey) { key = nextKey; since = now; }
    return { ...status, stableForMs: since === null ? 0 : now - since,
      stable: since !== null && now - since >= stableMs };
  };
}

// A phase timeout is evidence, even when recovery is still worth exercising.
// Hard deadline/RSS/browser failures must be checked by the caller first.
export function finishAdaptiveSettlePhase(phase, { sample, status, finishedAt, allowRecovery = false }) {
  Object.assign(phase, { sample, status, finishedAt, complete: status?.stable === true });
  if (phase.complete) return sample;
  phase.failure = `${phase.label}: complete adaptive view did not reach stable idle before phase deadline`;
  phase.recoveryContinued = allowRecovery;
  if (!allowRecovery) throw new Error(phase.failure);
  return sample;
}

export function adaptiveSettleAssertions(phases) {
  const settles = phases.filter(phase => phase.kind === 'settle');
  return {
    stableAllPhases: settles.length > 0 && settles.every(phase => phase.complete),
    requestedDetailSatisfied: settles.length > 0 && settles.every(phase => phase.complete && phase.status?.detailOutcome === 'policy-satisfied'),
  };
}

export function gradeAdaptiveOutcome(assertions, phases) {
  const outcomeBuckets = new Set(['requestedDetailSatisfied', 'adaptiveExercised']);
  if (assertions.completeScene !== true || Object.entries(assertions).some(([key, value]) => !outcomeBuckets.has(key) && value !== true)) return 'failed';
  if (phases.some(phase => phase.status?.detailOutcome === 'failed-levels')) return 'complete-view-with-failed-detail';
  if (assertions.requestedDetailSatisfied !== true) return 'complete-adaptive-view-with-budget-limitation';
  if (assertions.adaptiveExercised !== true) return 'complete-view-adaptive-exercise-inconclusive';
  return 'passed-default-adaptive';
}

export function summarizeIntervals(values) {
  const sorted = [...values].filter(Number.isFinite).sort((a, b) => a - b);
  const at = q => sorted.length ? sorted[Math.min(sorted.length - 1, Math.ceil(q * sorted.length) - 1)] : null;
  return { samples: sorted.length, p50: at(.5), p95: at(.95), max: at(1) };
}

// Same process-tree accounting as measure.mjs. Input is ps text so tests do not
// need a browser and can prove that a second renderer is not summed into a cap.
export function processMemoryFromPs(output, profileDirectory) {
  const rows = output.split('\n').flatMap(line => {
    const match = line.match(/^\s*(\d+)\s+(\d+)\s+(\d+)\s+(.*)$/);
    return match ? [{ pid: +match[1], ppid: +match[2], bytes: +match[3] * 1024, command: match[4] }] : [];
  });
  const ours = new Set(rows.filter(row => row.command.includes(profileDirectory)).map(row => row.pid));
  if (!ours.size) return null;
  for (let previous = -1; previous !== ours.size;) {
    previous = ours.size;
    for (const row of rows) if (ours.has(row.ppid)) ours.add(row.pid);
  }
  const result = {};
  for (const row of rows) {
    if (!ours.has(row.pid)) continue;
    const type = row.command.match(/--type=([a-zA-Z-]+)/)?.[1] || 'browser';
    const value = result[type] ||= { rssBytes: 0, largestPidBytes: 0, processCount: 0 };
    value.rssBytes += row.bytes;
    value.largestPidBytes = Math.max(value.largestPidBytes, row.bytes);
    value.processCount++;
  }
  return result;
}

export function mergeProcessPeak(peak, sample) {
  for (const [type, value] of Object.entries(sample || {})) {
    const current = peak[type] ||= { rssBytes: 0, largestPidBytes: 0, processCount: 0 };
    for (const key of Object.keys(current)) current[key] = Math.max(current[key], value[key]);
  }
  return peak;
}

